let myShader;
let img;

function preload() {
	myShader = loadShader('https://openprocessing.org/sketch/1048997/files/shader.vert', 'shader.frag');
}

function setup() {
	createCanvas(400, 400, WEBGL);
	img = loadImage('https://openprocessing.org/sketch/1048997/files/image.png');

	shader(myShader);
	myShader.setUniform('tex', img);

	noStroke();
	background(255);
}

function draw() {
	// lets map the (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) to frequency and (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) to amplitude
  // try playing with these to get a more or less distorted effect
  // 10 and 0.25 are just magic numbers that I thought looked good
  let freq = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 10.0);
  let amp = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, 0.25);

  myShader.setUniform('frequency', freq);
  myShader.setUniform('amplitude', amp);
	myShader.setUniform('time', frameCount * 0.01);

	rect(0, 0, width, height);
}

